CREATE UNIQUE INDEX "orders_refund_scope_unique" ON "orders" USING btree ("id","organization_id","event_id");--> statement-breakpoint
CREATE UNIQUE INDEX "payments_refund_scope_unique" ON "payments" USING btree ("id","order_id");--> statement-breakpoint
CREATE UNIQUE INDEX "refund_requests_scope_unique" ON "refund_requests" USING btree ("id","order_id","payment_id","organization_id","event_id");--> statement-breakpoint
ALTER TABLE "refund_requests" ADD CONSTRAINT "refund_requests_order_scope_fk" FOREIGN KEY ("order_id","organization_id","event_id") REFERENCES "public"."orders"("id","organization_id","event_id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "refund_requests" ADD CONSTRAINT "refund_requests_payment_scope_fk" FOREIGN KEY ("payment_id","order_id") REFERENCES "public"."payments"("id","order_id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "refunds" ADD CONSTRAINT "refunds_request_scope_fk" FOREIGN KEY ("request_id","order_id","payment_id","organization_id","event_id") REFERENCES "public"."refund_requests"("id","order_id","payment_id","organization_id","event_id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "refund_requests" ADD CONSTRAINT "refund_requests_review_status_check" CHECK ("refund_requests"."review_status" in ('pending_review', 'approved', 'rejected', 'withdrawn'));--> statement-breakpoint
ALTER TABLE "refund_requests" ADD CONSTRAINT "refund_requests_fulfillment_status_check" CHECK ("refund_requests"."fulfillment_status" is null or "refund_requests"."fulfillment_status" in ('open', 'completed', 'manual_required'));--> statement-breakpoint
ALTER TABLE "refunds" ADD CONSTRAINT "refunds_execution_shape_check" CHECK ("refunds"."source" not in ('wechat_api', 'external') or ("refunds"."payment_id" is not null and "refunds"."merchant_id" is not null and "refunds"."out_refund_no" is not null and "refunds"."amount" > 0 and "refunds"."currency" = 'CNY'));